  private methodTimeouts: Record<string, number>;
  private stdin: NodeJS.ReadableStream;
  private stdout: NodeJS.WritableStream;
  private buffer = "";
  private closed = false;

  constructor(options: JsonRpcFramingOptions = {}) {
    super();
