describe('JSON-RPC Type Guards', () => {
  describe('isRequest', () => {
    it('should identify valid requests', () => {
      const request = {
        jsonrpc: '2.0',
        id: 1,
        method: 'test',
        params: { foo: 'bar' },
      };
      expect(isRequest(request)).toBe(true);
    });

